def _dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = {}
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices[name] = [None] + versions

    best_vector = None
    best_versions = None
    for values in product(*(choices[name] for name in names)):
        selected = {name: value for name, value in zip(names, values)
                    if value is not None}
        rows = {name: next(row for row in packages[name]
                           if row["version"] == version)
                for name, version in selected.items()}
        valid = True
        for name, bounds in data["roots"].items():
            if name not in selected or not bounds[0] <= selected[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        edges = {}
        closure = set()
        pending = list(data["roots"])
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            if name not in selected:
                valid = False
                break
            closure.add(name)
            dependencies = [dep for dep in rows[name].get("deps", [])
                            if not dep.get("feature") or dep.get("feature") in features]
            edges[name] = []
            for dep in dependencies:
                other = dep["name"]
                edges[name].append(other)
                if (other not in selected or
                        not dep["min"] <= selected[other] <= dep["max"]):
                    valid = False
                    break
                pending.append(other)
        if not valid or closure != set(selected):
            continue

        active, finished = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in closure):
            continue

        vector = tuple(selected.get(name, -1) for name in order)
        if best_vector is None or (vector > best_vector if maximize else vector < best_vector):
            best_vector = vector
            best_versions = selected
    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _build_dependency_solver(order, maximize):
    return lambda data: _dependency_solver(data, order, maximize)


